package com.weiwei.wificast;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.net.*;import java.util.*;

public class MainActivity extends Activity {
 TextView status; ImageView preview; Spinner lens,quality; Handler h=new Handler(); Runnable refresh; Button copy; static final int PERMISSION=17; String url="";
 String address(){try{Enumeration<NetworkInterface> ni=NetworkInterface.getNetworkInterfaces();while(ni.hasMoreElements()){NetworkInterface n=ni.nextElement();if(!n.isUp()||n.isLoopback()||!n.getName().startsWith("wlan"))continue;Enumeration<InetAddress> aa=n.getInetAddresses();while(aa.hasMoreElements()){InetAddress a=aa.nextElement();if(a instanceof Inet4Address&&!a.isLoopbackAddress())return a.getHostAddress();}}}catch(Exception ignored){}return null;}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.rgb(22,30,49));v.setTextSize(size);return v;}
 void launch(){if(address()==null){Toast.makeText(this,"请先连接 Wi-Fi",Toast.LENGTH_LONG).show();return;} if(CastService.running){Toast.makeText(this,"请先停止投屏，再调整设置",Toast.LENGTH_LONG).show();return;} Intent i=new Intent(this,CastService.class);i.putExtra("front",lens.getSelectedItemPosition()==1);i.putExtra("hd",quality.getSelectedItemPosition()==1);try{startForegroundService(i);}catch(Exception e){Toast.makeText(this,"无法启动摄像头："+e.getMessage(),Toast.LENGTH_LONG).show();}}
 public void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setPadding(38,45,38,35);root.setOrientation(1);root.setBackgroundColor(Color.rgb(247,249,253));scroll.addView(root);TextView title=text("手机摄像头投屏",26);title.setTypeface(null,1);root.addView(title);TextView hint=text("手机与电脑连接同一 Wi-Fi。选择摄像头和清晰度，开始后在电脑浏览器打开网址。",15);hint.setPadding(0,20,0,15);root.addView(hint);lens=new Spinner(this);lens.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"后置摄像头","前置摄像头"}));root.addView(lens);quality=new Spinner(this);quality.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"60帧优先 · 720p（推荐）","高清 · 1080p（60帧视设备支持）"}));root.addView(quality);Button start=new Button(this);start.setText("开始摄像头投屏");root.addView(start);Button stop=new Button(this);stop.setText("停止投屏");root.addView(stop);status=text("尚未开始投屏",16);status.setTextIsSelectable(true);status.setPadding(0,20,0,10);root.addView(status);copy=new Button(this);copy.setText("复制电脑观看网址");root.addView(copy);preview=new ImageView(this);preview.setAdjustViewBounds(true);root.addView(preview,new LinearLayout.LayoutParams(-1,500));TextView note=text("电脑页面可旋转画面和全屏。调整清晰度或摄像头时，请先停止投屏。60帧取决于设备与网络，手机上显示实际采集帧数；电脑画面可能更低。只传画面，不传声音。",14);root.addView(note);setContentView(scroll);
 start.setOnClickListener(v->{if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},PERMISSION);else launch();});stop.setOnClickListener(v->stopService(new Intent(this,CastService.class)));copy.setOnClickListener(v->{if(url.isEmpty()){Toast.makeText(this,"请先开始投屏",Toast.LENGTH_SHORT).show();return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("投屏网址",url));Toast.makeText(this,"网址已复制，可通过微信发送到电脑",Toast.LENGTH_LONG).show();});refresh=()->{if(CastService.running){String ip=address();url=ip==null?"":"http://"+ip+":"+CastService.PORT+"/"+CastService.token;status.setText(url.isEmpty()?"请连接 Wi-Fi":"电脑打开：\n"+url+"\n\n"+CastService.status);byte[] f=CastService.frame;if(f!=null){Bitmap bm=BitmapFactory.decodeByteArray(f,0,f.length);if(bm!=null)preview.setImageBitmap(bm);}}else{url="";status.setText(CastService.status.isEmpty()?"尚未开始投屏":CastService.status);preview.setImageDrawable(null);}h.postDelayed(refresh,700);};h.post(refresh);}
 public void onRequestPermissionsResult(int req,String[] p,int[] g){super.onRequestPermissionsResult(req,p,g);if(req==PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)launch();else Toast.makeText(this,"需要摄像头权限才能投屏",Toast.LENGTH_LONG).show();}
 protected void onDestroy(){h.removeCallbacks(refresh);super.onDestroy();}
}
